fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Limit the slice to at most n participants
    let limit = n as usize;
    let considered = &participations[..participations.len().min(limit)];

    // Count eligible participants
    let eligible_count = considered.iter()
        .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
        .count();

    // Number of teams is eligible_count // 3
    (eligible_count / 3) as u8
}